-- mod-temucraft-models: generated by tools/gen_models.py, do not edit by hand.
-- Display rows, showcase creatures and fully cosmetic items for models that ship in the Temucraft client patches
-- but had no display row, plus cosmetic outfits from city guards. Ids are the variables below; every block deletes its
-- own range first, so the file can be run again. The client needs the same rows (client/DBFilesClient).
SET @CMD  := 46000;
 -- CreatureModelData
SET @CDI  := 1210000;
 -- CreatureDisplayInfo
SET @IDI  := 1210000;
 -- ItemDisplayInfo
SET @CRE  := 1210000;
 -- creature_template
SET @ITEM := 1210000;
 -- item_template, Item.dbc (looks from the free models)
SET @OUT  := 1220000;
 -- item_template, Item.dbc (NPC outfits)
SET @ODI  := 1220000;
 -- ItemDisplayInfo (NPC looks given an icon)
SET @SET  := 4000;
 -- ItemSet (one per outfit)
DELETE FROM `creaturemodeldata_dbc` WHERE `ID` BETWEEN @CMD AND @CMD+2999;
CREATE TEMPORARY TABLE `tmp_shrink` LIKE `creaturemodeldata_dbc`;
UPDATE `tmp_shrink` SET `ID`=`ID`+@CMD,`BloodID`=1,`FootprintParticleScale`=1,`WorldEffectScale`=1,`AttachedEffectScale`=1;
DROP TEMPORARY TABLE `tmp_shrink`;
CREATE TEMPORARY TABLE `tmp_shrink` LIKE `creaturemodeldata_dbc`;
UPDATE `tmp_shrink` SET `ID`=`ID`+@CMD,`BloodID`=1,`FootprintParticleScale`=1,`CollisionWidth`=0.611111,`CollisionHeight`=2.031278,`WorldEffectScale`=1,`AttachedEffectScale`=1;
DROP TEMPORARY TABLE `tmp_shrink`;

